<h1>Trade Review #<?=e($trade['id'])?></h1>
<div class="card"><div class="grid"><p><strong>Symbol</strong><br><?=e($trade['symbol'])?></p><p><strong>Side</strong><br><?=e(ucfirst($trade['side']))?></p><p><strong>Quantity</strong><br><?=number_format((float)$trade['quantity'],4)?></p><p><strong>Entry</strong><br><?=e($trade['entry_price'])?></p><p><strong>Exit</strong><br><?=e($trade['exit_price']??'—')?></p><p><strong>Closed</strong><br><?=e($trade['closed_at']??'—')?></p></div></div>
<form method="post" class="card"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="grid"><p><label>Review status</label><select name="review_status"><option value="pending" <?=$trade['review_status']==='pending'?'selected':''?>>Pending</option><option value="reviewed" <?=$trade['review_status']==='reviewed'?'selected':''?>>Reviewed</option><option value="needs_followup" <?=$trade['review_status']==='needs_followup'?'selected':''?>>Needs follow-up</option></select></p><p><label>Review due</label><input type="datetime-local" name="review_due_at" value="<?=!empty($trade['review_due_at'])?e(date('Y-m-d\\TH:i',strtotime($trade['review_due_at']))):''?>"></p></div><p><label>Review note</label><textarea name="review_note"><?=e($trade['review_note']??'')?></textarea></p><button>Save review</button> <a href="/review-queue">Cancel</a></form>
